import random,string
import modules.capture_audit as ca
from modules.byte_program import Capture,literal
random.seed(88)
def field():
 return random.choice(['Host','X','Y','Content-Type','hOsT'])+': '+random.choice(['a','x y','Host','0','chunked','1, 1',''])+'\r\n'
def gen_req():
 method=random.choice(['GET','POST','X'])
 target=random.choice(['/','/x','*','/a?b'])
 headers=[]
 for _ in range(random.randrange(0,5)):headers.append(field())
 framing=random.choice(['none','length','chunked'])
 body=''
 if framing=='length':
  n=random.randrange(0,5);headers.append(f'Content-Length: {n}\r\n');body=bytes(random.randrange(256) for _ in range(n)).decode('latin1')
 elif framing=='chunked':
  headers.append('Transfer-Encoding: Chunked\r\n');branches=[]
  for _ in range(random.randrange(0,4)):
   n=random.randrange(0,5);branches.append(f'{n:x}'+random.choice(['', ';ext'])+'\r\n'+('a'*n)+'\r\n')
  trailers=[]
  for _ in range(random.randrange(0,4)):
   trailers.append(random.choice(['A','B'])+': '+random.choice(['1',' v '])+'\r\n')
  body=''.join(branches)+'0\r\n'+''.join(trailers)+'\r\n'
 req=(method+' '+target+' HTTP/1.1\r\n'+''.join(headers)+'\r\n'+body)
 return req.encode('latin1')
for trial in range(2000):
 capbytes=b''.join(gen_req() for _ in range(random.randrange(1,6)))
 cap=Capture([(None,literal(capbytes))])
 def parse(fast):
  old=ca._field_block_fast
  if not fast:ca._field_block_fast=ca._field_block_slow
  state=ca._AuditState();pos=0;recs=[]
  try:
   while pos<len(capbytes):
    start=pos
    try:p,e=ca._parse_request(cap,start,state)
    except ca._ParseFailure as ex:
     return ('fail',ex.kind,start,recs,state.chunk_lines)
    recs.append((p.start,p.end,p.method,p.target,p.host_value,p.host_count,p.headers_fp,p.body_fp,p.trailers_fp,p.framing,p.owner,p.owners));pos=e
   return ('ok',pos,recs,state.chunk_lines)
  finally:ca._field_block_fast=old
 a=parse(True);b=parse(False)
 if a!=b:
  print('MISMATCH trial',trial,repr(capbytes),a,b);break
else:print('valid request fast/slow match')
